package com.arena.core.checkin;
import static com.arena.core.checkin.FacilityCheckinContracts.*;
import com.arena.core.training.*;import com.arena.core.facility.FacilityService;import com.arena.core.sessions.*;import com.arena.core.publicclub.*;import com.arena.core.exception.*;
import java.time.*;import java.util.*;import java.security.SecureRandom;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.oauth2.jwt.Jwt;
@Service @Transactional @RequiredArgsConstructor
public class PermanentCheckinService {
 private final AcademyAuthorization auth;private final FacilityService facilities;private final AcademyPlayAreaRepository areas;private final AcademySportRepository sports;private final FacilityPermanentQrRepository qrs;private final FacilityQrChallengeRepository forms;private final FacilityCustomerCheckinRepository checkins;private final FacilityMobileLimitRepository limits;private final PublicClubService clubs;private final ClubCustomerService customers;private final RunningSessionService lifecycle;
 private static final SecureRandom RANDOM=new SecureRandom();
 private String random(){byte[] b=new byte[32];RANDOM.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
 private boolean allowed(AcademyAuthorization.Actor a,Long sport){return a.manager()||a.roles().contains("STAFF")||a.membership()!=null&&(a.roles().contains("INSTRUCTOR")||"COACH".equals(a.membership().getRole()))&&a.membership().getSportIds().contains(sport);}
 private AcademyPlayArea area(Long academy,Long id){return areas.findById(id).filter(f->f.getAcademyId().equals(academy)).orElseThrow(()->new ArenaOpsException(ErrorCode.RESOURCE_NOT_FOUND));}
 private void operator(AcademyAuthorization.Actor a,AcademyPlayArea f){if(!allowed(a,f.getSportId()))throw new ArenaOpsException(ErrorCode.ACCESS_DENIED);}
 private void eligible(AcademyPlayArea f){if(!clubs.eligible(f,sports.findByAcademyIdOrderByName(f.getAcademyId())))throw new ArenaOpsException(ErrorCode.QR_CHECKIN_UNAVAILABLE);}
 private Challenge response(FacilityPermanentQr q){var f=area(q.getAcademyId(),q.getFacilityId());return new Challenge(q.getPublicId(),f.getDisplayName()==null?f.getCode():f.getDisplayName(),null,clubs.checkinOrigin(q.getAcademyId())+"/check-in#"+q.getPublicId());}
 public Challenge issue(Jwt jwt,Long id){var a=auth.actor(jwt);var f=facilities.requireEligibleLocked(jwt,a.academyId(),id);operator(a,f);eligible(f);var q=qrs.locked(a.academyId(),id).orElseGet(()->{var v=new FacilityPermanentQr();v.setAcademyId(a.academyId());v.setFacilityId(id);v.setPublicId(random());return qrs.saveAndFlush(v);});if(q.isRevoked())throw new ArenaOpsException(ErrorCode.QR_CHECKIN_UNAVAILABLE);return response(q);}
 public void revoke(Jwt jwt,Long id){var a=auth.owner(jwt);var q=qrs.locked(a.academyId(),id).orElseThrow(()->new ArenaOpsException(ErrorCode.RESOURCE_NOT_FOUND));q.setRevoked(true);qrs.save(q);}
 public Challenge regenerate(Jwt jwt,Long id){var a=auth.owner(jwt);var q=qrs.locked(a.academyId(),id).orElseThrow(()->new ArenaOpsException(ErrorCode.RESOURCE_NOT_FOUND));q.setPublicId(random());q.setRevoked(false);qrs.saveAndFlush(q);return response(q);}
 public void clearCooldown(Jwt jwt,Long id){var a=auth.operations(jwt);var q=qrs.locked(a.academyId(),id).orElseThrow(()->new ArenaOpsException(ErrorCode.RESOURCE_NOT_FOUND));q.setSuspendedUntil(null);q.setQuotaResetAt(Instant.now());qrs.save(q);}
 private FacilityPermanentQr scoped(String slug,String token){if(token==null||!token.matches("[A-Za-z0-9_-]{43}"))throw new ArenaOpsException(ErrorCode.QR_CHECKIN_UNAVAILABLE);var q=qrs.byPublicId(token).filter(v->!v.isRevoked()).orElseThrow(()->new ArenaOpsException(ErrorCode.QR_CHECKIN_UNAVAILABLE));if(slug!=null&&!q.getAcademyId().equals(clubs.checkinAcademy(slug)))throw new ArenaOpsException(ErrorCode.QR_CHECKIN_UNAVAILABLE);clubs.checkinCustomer(q.getAcademyId());eligible(area(q.getAcademyId(),q.getFacilityId()));return q;}
 public PublicInfo inspect(String slug,String token){var q=scoped(slug,token);String form=random();var now=Instant.now();var f=new FacilityQrChallenge();f.setAcademyId(q.getAcademyId());f.setFacilityId(q.getFacilityId());f.setPermanentQrId(q.getFacilityId());f.setTokenHash(ClubCustomerService.hash(form));f.setCreatedAt(now);f.setExpiresAt(now.plusSeconds(300));forms.save(f);var label=area(q.getAcademyId(),q.getFacilityId());return new PublicInfo(label.getDisplayName()==null?label.getCode():label.getDisplayName(),f.getExpiresAt(),form);}

 @Transactional(noRollbackFor=PublicLimitException.class)
 public Receipt submit(String slug,Submission r){
  String name=ClubCustomerService.name(r.name()),mobile=ClubCustomerService.checkinMobile(r.mobile());if(!r.privacyAccepted()||r.requestId()==null||r.website()!=null&&!r.website().isBlank()||r.formToken()==null)throw new ArenaOpsException(ErrorCode.INVALID_REQUEST);
  var q=scoped(slug,r.token());String fingerprint=ClubCustomerService.hash(name+"\n"+mobile+"\n"+r.formToken());var prior=checkins.findByAcademyIdAndFacilityIdAndRequestId(q.getAcademyId(),q.getFacilityId(),r.requestId());if(prior.isPresent()){if(!fingerprint.equals(prior.get().getRequestHash()))throw new ArenaOpsException(ErrorCode.CONFLICT);return new Receipt(prior.get().getStatus(),prior.get().getExpiresAt());}
  var form=forms.locked(ClubCustomerService.hash(r.formToken())).filter(f->Objects.equals(f.getPermanentQrId(),q.getFacilityId())&&f.getAcademyId().equals(q.getAcademyId())).orElseThrow(()->new ArenaOpsException(ErrorCode.QR_CHECKIN_UNAVAILABLE));var now=Instant.now();if(form.getUsedAt()!=null||!form.getExpiresAt().isAfter(now)||form.getCreatedAt()==null||form.getCreatedAt().plusSeconds(2).isAfter(now))throw new ArenaOpsException(ErrorCode.QR_CHECKIN_UNAVAILABLE);
  if(q.getSuspendedUntil()!=null&&q.getSuspendedUntil().isAfter(now))throw new PublicLimitException();
  checkins.expireFacility(q.getAcademyId(),q.getFacilityId(),now);if(checkins.existsByAcademyIdAndFacilityIdAndStatus(q.getAcademyId(),q.getFacilityId(),"PENDING"))throw new ArenaOpsException(ErrorCode.CONFLICT);
  String hash=ClubCustomerService.hash(mobile);var limit=limits.findByFacilityIdAndMobileHash(q.getFacilityId(),hash);if(limit.isPresent()&&limit.get().getBlockedUntil().isAfter(now))throw new PublicLimitException();
  long mobileCount=checkins.countByAcademyIdAndFacilityIdAndMobileHashAndCreatedAtAfter(q.getAcademyId(),q.getFacilityId(),hash,now.minusSeconds(1800));if(mobileCount>=2){var l=limit.orElseGet(FacilityMobileLimit::new);l.setFacilityId(q.getFacilityId());l.setMobileHash(hash);l.setBlockedUntil(now.plusSeconds(1800));limits.saveAndFlush(l);throw new PublicLimitException();}
  long count=checkins.countByAcademyIdAndFacilityIdAndCreatedAtAfter(q.getAcademyId(),q.getFacilityId(),(q.getQuotaResetAt()!=null&&q.getQuotaResetAt().isAfter(now.minusSeconds(1800))?q.getQuotaResetAt():now.minusSeconds(1800)));if(count>=4){q.setSuspendedUntil(now.plusSeconds(1800));qrs.saveAndFlush(q);throw new PublicLimitException();}
  var c=new FacilityCustomerCheckin();c.setAcademyId(q.getAcademyId());c.setFacilityId(q.getFacilityId());c.setChallengeId(form.getId());c.setCustomerName(name);c.setMobile(mobile);c.setMobileHash(hash);c.setRequestId(r.requestId());c.setRequestHash(fingerprint);c.setStatus("PENDING");c.setCreatedAt(now);c.setExpiresAt(now.plusSeconds(120));form.setUsedAt(now);forms.save(form);checkins.saveAndFlush(c);if(count+1>=4){q.setSuspendedUntil(now.plusSeconds(1800));qrs.save(q);}return new Receipt("PENDING",c.getExpiresAt());
 }
 public List<Pending> pending(Jwt jwt){var a=auth.actor(jwt);return checkins.findTop100ByAcademyIdAndStatusAndExpiresAtAfterOrderByCreatedAtAsc(a.academyId(),"PENDING",Instant.now()).stream().filter(c->allowed(a,area(a.academyId(),c.getFacilityId()).getSportId())).map(c->new Pending(c.getId(),c.getFacilityId(),area(a.academyId(),c.getFacilityId()).getCode(),c.getCustomerName(),c.getMobile(),false,c.getCreatedAt(),c.getExpiresAt())).toList();}
 public Confirmation confirm(Jwt jwt,Long id,Confirm r){var a=auth.actor(jwt);var hint=checkins.findById(id).filter(c->c.getAcademyId().equals(a.academyId())).orElseThrow(()->new ArenaOpsException(ErrorCode.RESOURCE_NOT_FOUND));qrs.locked(a.academyId(),hint.getFacilityId());var c=checkins.locked(a.academyId(),id).orElseThrow();operator(a,area(a.academyId(),c.getFacilityId()));if(!"PENDING".equals(c.getStatus())||!c.getExpiresAt().isAfter(Instant.now()))throw new ArenaOpsException(ErrorCode.QR_CHECKIN_UNAVAILABLE);var session=lifecycle.start(jwt,new RunningSessionContracts.Start(c.getFacilityId(),c.getCustomerName(),r.plannedEndAt()));if(!c.getExpiresAt().isAfter(Instant.now()))throw new ArenaOpsException(ErrorCode.QR_CHECKIN_UNAVAILABLE);c.setStatus("CONFIRMED");c.setSessionId(session.id());c.setConfirmedAt(Instant.now());c.setConfirmedBy(a.user().getUsername());c.setCustomerId(customers.visit(a.academyId(),c.getCustomerName(),c.getMobile(),session.id(),c.getConfirmedAt()));checkins.save(c);return new Confirmation(session.id(),"STARTED");}
 @org.springframework.scheduling.annotation.Scheduled(fixedDelayString="${arena.checkin.cleanup-ms:300000}") public void cleanup(){limits.purge(Instant.now().minusSeconds(86400));}
 public void cancel(Jwt jwt,Long id){var a=auth.actor(jwt);var hint=checkins.findById(id).filter(c->c.getAcademyId().equals(a.academyId())).orElseThrow(()->new ArenaOpsException(ErrorCode.RESOURCE_NOT_FOUND));qrs.locked(a.academyId(),hint.getFacilityId());var c=checkins.locked(a.academyId(),id).orElseThrow();operator(a,area(a.academyId(),c.getFacilityId()));if(!"PENDING".equals(c.getStatus()))throw new ArenaOpsException(ErrorCode.CONFLICT);c.setStatus("REJECTED");c.setCustomerName(null);c.setMobile(null);checkins.save(c);}
}
